// @flow strict-local

export function windowSmoothScroll(x: number, y: number) {
  // TODO use built-in version if present

  const performanceNow =
    window.performance && window.performance.now
      ? window.performance.now.bind(window.performance)
      : Date.now;

  const duration = 468;

  function easing(o) {
    return 0.5 * (1 - Math.cos(Math.PI * o));
  }

  function smoothScrollImpl(o) {
    const timeFraction = (performanceNow() - o.startTime) / duration;
    const fractionComplete = easing(timeFraction > 1 ? 1 : timeFraction);
    const curX = o.startX + (o.x - o.startX) * fractionComplete;
    const curY = o.startY + (o.y - o.startY) * fractionComplete;

    // This line attempts an "instant" scroll to where we want to be right now.
    window.scroll(curX, curY);

    // And then this `requestAnimationFrame` is to let us repeat that until it's done.
    if (!(curX === o.x && curY === o.y)) {
      window.requestAnimationFrame(smoothScrollImpl.bind(window, o));
    }
  }

  smoothScrollImpl({
    startTime: performanceNow(),
    startX: window.scrollX,
    startY: window.scrollY,
    x,
    y,
  });
}
